  <div class="worksheet-builder-page">
    <div id="appBarContainer"></div>
    <div class="worksheet-floating-controls">
      <button
        id="worksheetFullscreenBtn"
        type="button"
        class="worksheet-fullscreen-btn fullscreen-button"
        aria-label="Enter full screen"
        aria-pressed="false"
      >
        <span class="tool-icon icon-maximize" data-lucide="maximize" aria-hidden="true"></span>
        <span class="tool-icon icon-minimize" data-lucide="minimize" aria-hidden="true"></span>
      </button>
    </div>
    <div id="worksheetLandscapeOverlay" class="worksheet-landscape-overlay" hidden>
      <div class="worksheet-landscape-card">
        <h2>Rotate To Landscape</h2>
        <p>Worksheet Builder is optimized for pen and touch use in landscape orientation.</p>
      </div>
    </div>
    <div class="worksheet-builder-layout">
      <aside class="worksheet-panel worksheet-library-panel">
        <div class="worksheet-library-filters">
          <div class="pdf-panel-search worksheet-library-search">
            <input
              id="worksheetLibrarySearch"
              type="search"
              placeholder="Search by filename, year, or session"
            />
          </div>
          <div class="pdf-panel-filters worksheet-library-filter-groups">
            <div class="pdf-panel-filter-row pdf-panel-filter-row-tutor" role="group" aria-label="Curriculum filters">
              <label class="pdf-filter-checkbox">
                <input type="checkbox" id="worksheetFilterALevels" checked />
                <span>A-Levels</span>
              </label>
              <label class="pdf-filter-checkbox">
                <input type="checkbox" id="worksheetFilterAS" checked />
                <span>AS</span>
              </label>
              <label class="pdf-filter-checkbox">
                <input type="checkbox" id="worksheetFilterIGExt" checked />
                <span>IG Ext</span>
              </label>
              <label class="pdf-filter-checkbox">
                <input type="checkbox" id="worksheetFilterIGCore" checked />
                <span>IG Core</span>
              </label>
            </div>
            <div class="pdf-panel-filter-row pdf-panel-filter-row-docs" role="group" aria-label="Source filters">
              <label class="pdf-filter-checkbox">
                <input type="checkbox" id="worksheetSourcePapersChip" checked />
                <span>QP</span>
              </label>
              <label class="pdf-filter-checkbox">
                <input type="checkbox" id="worksheetSourceNotesChip" />
                <span>Notes</span>
              </label>
              <label class="pdf-filter-checkbox">
                <input type="checkbox" id="worksheetSourceExistingChip" />
                <span>WS</span>
              </label>
            </div>
          </div>
        </div>
        <section class="worksheet-library-section">
          <div
            id="worksheetExistingControls"
            class="worksheet-library-header-row"
            hidden
          >
            <div class="worksheet-sort-controls">
              <label class="worksheet-sort-label" for="worksheetSortSelect">Sort</label>
              <select id="worksheetSortSelect" class="worksheet-sort-select" aria-label="Sort worksheets">
                <option value="name-asc">Name A-Z</option>
                <option value="name-desc">Name Z-A</option>
                <option value="date-created-desc">Date Created Newest</option>
                <option value="date-created-asc">Date Created Oldest</option>
                <option value="date-modified-desc">Date Modified Newest</option>
                <option value="date-modified-asc">Date Modified Oldest</option>
              </select>
            </div>
          </div>
          <div id="worksheetLibraryStatus" class="worksheet-status" role="status"></div>
          <div id="worksheetPapersPanel" class="worksheet-library-panel-body" role="tabpanel">
            <div class="worksheet-scroll-region" id="worksheetPapersScroll">
              <ul id="worksheetPapersList" class="worksheet-papers-list" aria-label="Available PDFs"></ul>
            </div>
          </div>
          <div id="worksheetNotesPanel" class="worksheet-library-panel-body" role="tabpanel" hidden>
            <div class="worksheet-scroll-region" id="worksheetNotesScroll">
              <ul id="worksheetNotesList" class="worksheet-papers-list" aria-label="Available notes"></ul>
            </div>
          </div>
          <div id="worksheetExistingPanel" class="worksheet-library-panel-body" role="tabpanel" hidden>
            <div class="worksheet-scroll-region" id="worksheetExistingScroll">
              <ul id="worksheetExistingList" class="worksheet-existing-list" aria-label="Existing worksheets"></ul>
            </div>
          </div>
        </section>
        <section class="worksheet-library-section">
          <h2>Uploads</h2>
          <div
            id="worksheetExistingUploadRow"
            class="worksheet-upload-row"
          >
            <button id="worksheetUploadBtn" type="button">Upload PDFs or MS Word templates</button>
            <button id="worksheetPasteClipboardBtn" type="button" title="Paste image from OS clipboard (Ctrl/Cmd+V)">Paste image from clipboard</button>
            <input
              id="worksheetUploadInput"
              type="file"
              accept="application/pdf,.pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,.docx"
              multiple
              hidden
            />
          </div>
        </section>
      </aside>
      <section class="worksheet-panel worksheet-viewer-panel">
        <div class="worksheet-viewer-body">
          <aside id="worksheetPageThumbnails" class="worksheet-page-thumbnails" aria-label="PDF pages"></aside>
          <div id="worksheetCanvasShell" class="worksheet-canvas-shell">
            <div class="stroke-loading" id="worksheetStrokeLoading" role="status" aria-live="polite" hidden>
              <div class="stroke-loading-card">
                <span class="stroke-loading-spinner" aria-hidden="true"></span>
                <span class="stroke-loading-text" id="worksheetStrokeLoadingLabel">Loading…</span>
              </div>
            </div>
            <div id="worksheetHintToast" class="worksheet-hint-toast" hidden></div>
            <div id="worksheetStartGuidance" class="worksheet-start-guidance" hidden></div>
            <div id="worksheetSelectionGuidance" class="worksheet-selection-guidance" hidden></div>
            <button
              id="worksheetEditCloseBtn"
              type="button"
              class="worksheet-edit-close-btn"
              aria-label="Close worksheet edit mode"
              title="Close worksheet edit mode"
              hidden
            >
              ×
            </button>
            <div id="worksheetCanvasHost" class="worksheet-canvas-host">
              <canvas id="worksheetPdfCanvas"></canvas>
              <div id="worksheetSelectionLayer" class="worksheet-selection-layer" aria-label="Selection layer"></div>
            </div>
          </div>
        </div>
      </section>
      <aside class="worksheet-panel worksheet-questions-panel">
        <h2>Selected Questions</h2>
        <div class="worksheet-controls-row">
          <label class="worksheet-control-label" for="worksheetTitleInput">Title</label>
          <input id="worksheetTitleInput" type="text" value="" />
          <button id="worksheetGenerateBtn" type="button">Generate New Worksheet</button>
          <button id="worksheetClearQuestionsBtn" type="button" disabled>Clear</button>
        </div>
        <div id="worksheetSubjectWarning" class="worksheet-status" role="alert" hidden></div>
        <ul id="worksheetQuestionsList" class="worksheet-questions-list" aria-label="Selected questions"></ul>
        <div id="worksheetPreviewPopup" class="worksheet-preview-popup" hidden>
          <button id="worksheetPreviewClose" class="worksheet-preview-close" type="button" aria-label="Close preview">×</button>
          <canvas id="worksheetPreviewCanvas"></canvas>
        </div>
      </aside>
    </div>
    <div id="uploadAssociationModal" class="upload-association-modal" hidden>
      <div class="upload-association-modal__backdrop" data-close-modal="true"></div>
      <div
        class="upload-association-modal__dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="uploadAssociationModalTitle"
      >
        <h3 id="uploadAssociationModalTitle">Associate upload with student</h3>
        <p id="uploadAssociationPrompt" class="upload-association-modal__prompt"></p>
        <div
          id="uploadAssociationStudentRow"
          class="upload-association-modal__field"
          hidden
        >
          <label for="uploadAssociationStudentSelect">Select student</label>
          <select id="uploadAssociationStudentSelect"></select>
        </div>
        <div class="upload-association-modal__field">
          <label for="uploadAssociationNoteInput">Version note</label>
          <input id="uploadAssociationNoteInput" type="text" maxlength="280" />
        </div>
        <label class="upload-association-modal__checkbox">
          <input id="uploadAssociationAllowV1Input" type="checkbox" />
          <span>Allow student to view v1 (global/shared version)</span>
        </label>
        <div class="upload-association-modal__actions">
          <button id="uploadAssociationCancelBtn" type="button">Cancel upload</button>
          <button id="uploadAssociationConfirmBtn" type="button">Associate as v2</button>
        </div>
      </div>
    </div>
    <div id="worksheetUnsavedModal" class="worksheet-unsaved-modal" hidden>
      <div class="worksheet-unsaved-modal__backdrop" data-close-unsaved-modal="true"></div>
      <div
        class="worksheet-unsaved-modal__dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="worksheetUnsavedModalTitle"
      >
        <h3 id="worksheetUnsavedModalTitle">Unsaved changes</h3>
        <p>Save changes before closing edit mode?</p>
        <div class="worksheet-unsaved-modal__actions">
          <button id="worksheetUnsavedCancelBtn" type="button">Cancel</button>
          <button id="worksheetUnsavedDiscardBtn" type="button">Close without saving</button>
          <button id="worksheetUnsavedSaveBtn" type="button">Save changes</button>
        </div>
      </div>
    </div>
    <div id="worksheetSourcesGuidanceModal" class="bug-reporter-modal" hidden>
      <div
        class="bug-reporter-modal-card"
        role="dialog"
        aria-modal="true"
        aria-labelledby="worksheetSourcesGuidanceTitle"
      >
        <h4 id="worksheetSourcesGuidanceTitle">Sources</h4>
        <p>Past papers, notes and existing worksheets can be used as question sources.</p>
        <label class="bug-reporter-modal-dismiss">
          <input
            id="worksheetSourcesGuidanceDismissInput"
            type="checkbox"
            class="bug-reporter-modal-dismiss-input"
          />
          Don't show this guidance again
        </label>
        <div class="bug-reporter-modal-actions">
          <button
            id="worksheetSourcesGuidanceContinueBtn"
            type="button"
            class="bug-reporter-modal-start"
          >
            Continue
          </button>
        </div>
      </div>
    </div>
  </div>
